begin;
create function private.brochure_resolve(business text,slug text) returns uuid language sql stable security definer set search_path='' as $$select b.id from public.brochures b join public.organizations o on o.id=b.organization_id join public.brochure_versions v on v.id=b.published_version_id where o.slug=$1 and b.slug=$2 and b.status='published' and private.entitled(o.id,'brochure') and (private.brochure_config(o.id)->>'public_share')::boolean and v.snapshot->'settings'->>'sharing'='true';$$;
create function public.brochure_public(p_business text,p_slug text,p_action text default 'read',p_asset_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$declare b public.brochures;v public.brochure_versions;a public.website_assets;kind text;begin
 select * into b from public.brochures where id=private.brochure_resolve(p_business,p_slug);if b.id is null then return null;end if;
 select * into v from public.brochure_versions where id=b.published_version_id;
 if p_action='read' then return jsonb_build_object('document',v.snapshot,'sequence',v.sequence,'businessName',v.business_name,'publishedAt',v.created_at,'formsEnabled',private.entitled(b.organization_id,'crm') and v.snapshot->'form'->>'enabled'='true');
 elsif p_action='asset' then if p_asset_id not in(select private.brochure_assets(v.snapshot)) then return null;end if;select * into a from public.website_assets where organization_id=b.organization_id and id=p_asset_id and status='ready';if a.id is null then return null;end if;return jsonb_build_object('mime',a.mime,'data',(select encode(data,'base64') from private.website_asset_data where asset_id=a.id));
 elsif p_action='pdf' then if v.snapshot->'settings'->>'download'<>'true' then return null;end if;kind='download';
 elsif p_action in ('view','cta') then kind=p_action;
 else return null;end if;
 if (private.brochure_config(b.organization_id)->>'analytics')::boolean then insert into private.brochure_metrics(brochure_id,day,kind,hits) values(b.id,current_date,kind,1) on conflict(brochure_id,day,kind) do update set hits=least(private.brochure_metrics.hits+1,1000000);end if;
 if p_action='pdf' then return jsonb_build_object('data',(select encode(data,'base64') from private.brochure_pdfs where version_id=v.id),'title',v.snapshot->>'title','sequence',v.sequence);end if;return '{}';
end$$;
create function public.brochure_sitemap(p_business text) returns jsonb language plpgsql stable security definer set search_path='' as $$begin return(select coalesce(jsonb_agg(x),'[]') from(select b.slug,v.created_at updated from public.brochures b join public.organizations o on o.id=b.organization_id join public.brochure_versions v on v.id=b.published_version_id where o.slug=p_business and b.id=private.brochure_resolve(p_business,b.slug) and v.snapshot->'settings'->>'index'='true' order by b.slug limit 200)x);end$$;
create function public.brochure_submit_lead(p_business text,p_slug text,p_page text,p_values jsonb,p_honeypot text default '') returns jsonb language plpgsql security definer set search_path='' as $$declare b public.brochures;v public.brochure_versions;form jsonb;name text;phone text;email text;notes text='';location text;source uuid;stage uuid;lead uuid;k text;hits integer;bucket timestamptz;counter bigint;prefix text;yr integer;begin
 select * into b from public.brochures where id=private.brochure_resolve(p_business,p_slug);if b.id is null then raise exception 'Form unavailable' using errcode='42501';end if;perform 1 from public.organizations where id=b.organization_id for update;
 if private.brochure_resolve(p_business,p_slug) is distinct from b.id or not private.entitled(b.organization_id,'crm') then raise exception 'Form unavailable' using errcode='42501';end if;select * into b from public.brochures where id=b.id;select * into v from public.brochure_versions where id=b.published_version_id;form=v.snapshot->'form';
 if form->>'enabled' is distinct from 'true' or not exists(select 1 from jsonb_array_elements(v.snapshot->'pages') p where p->>'id'=p_page) then raise exception 'Form unavailable' using errcode='42501';end if;
 if jsonb_typeof(p_values) is distinct from 'object' or octet_length(p_values::text)>12000 then raise exception 'Invalid enquiry' using errcode='22023';end if;
 bucket=date_trunc('minute',now());insert into private.brochure_form_limits(brochure_id,bucket,hits) values(b.id,bucket,1) on conflict(brochure_id,bucket) do update set hits=private.brochure_form_limits.hits+1 returning private.brochure_form_limits.hits into hits;delete from private.brochure_form_limits where brochure_id=b.id and bucket<now()-interval '1 day';
 if hits>60 then return jsonb_build_object('accepted',false,'message','Please try again shortly.');end if;
 if coalesce(p_honeypot,'')<>'' then return jsonb_build_object('accepted',true,'message',form->>'confirmation');end if;
 for k in select jsonb_object_keys(p_values) loop if k not in ('name','phone','consent') and not (form->'fields')?k then raise exception 'Unknown field' using errcode='22023';end if;if k<>'consent' and (jsonb_typeof(p_values->k)<>'string' or length(p_values->>k)>2000) then raise exception 'Invalid field' using errcode='22023';end if;end loop;
 name=trim(p_values->>'name');phone=private.normalize_crm_phone(p_values->>'phone');email=lower(trim(coalesce(p_values->>'email','')));location=left(coalesce(p_values->>'location',''),500);
 if p_values->'consent' is distinct from 'true'::jsonb or name is null or length(name) not between 1 and 200 or phone is null or phone !~ '^\+?[0-9]{7,15}$' or length(email)>254 or email<>'' and email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Name, valid phone and consent required' using errcode='22023';end if;
 foreach k in array array['requirement','location','budget','message'] loop if p_values ? k then notes=notes||k||': '||(p_values->>k)||E'\n';end if;end loop;
 select id into source from public.lead_sources where organization_id=b.organization_id and key='brochure' and active;select id into stage from public.crm_pipeline_stages where organization_id=b.organization_id and active and outcome='open' order by sort_order,id limit 1;if source is null or stage is null then raise exception 'Form temporarily unavailable' using errcode='23514';end if;
 select id into lead from public.leads where organization_id=b.organization_id and lifecycle<>'archived' and (phone_normalized=phone or email<>'' and email_normalized=email) order by created_at,id limit 1;
 if lead is null then yr=extract(year from current_date);insert into private.lead_number_sequences(organization_id,year,last_number) values(b.organization_id,yr,1) on conflict(organization_id,year) do update set last_number=private.lead_number_sequences.last_number+1 returning last_number,private.lead_number_sequences.prefix into counter,prefix;insert into public.leads(organization_id,lead_number,name,phone,email,source_id,source_detail,stage_id,location,notes) values(b.organization_id,prefix||'-'||yr||'-'||lpad(counter::text,6,'0'),name,phone,email,source,left((v.snapshot->>'title')||' / Version '||v.sequence||' / '||p_page,500),stage,location,notes) returning id into lead;end if;
 perform private.crm_event(b.organization_id,lead,'system','Brochure enquiry received with explicit consent',jsonb_build_object('brochure',b.id,'brochureName',v.snapshot->>'title','version',v.id,'sequence',v.sequence,'page',p_page,'cta',form->>'label','consent',true));
 if (private.brochure_config(b.organization_id)->>'analytics')::boolean then insert into private.brochure_metrics(brochure_id,day,kind,hits) values(b.id,current_date,'lead',1) on conflict(brochure_id,day,kind) do update set hits=private.brochure_metrics.hits+1;end if;
 return jsonb_build_object('accepted',true,'message',form->>'confirmation');
end$$;
create function public.brochure_metrics_read(p_organization_id uuid,p_brochure_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$begin if not private.brochure_access(p_organization_id,'brochure.analytics.view') or not (private.brochure_config(p_organization_id)->>'analytics')::boolean or not exists(select 1 from public.brochures where organization_id=p_organization_id and id=p_brochure_id) then raise exception 'Metrics unavailable' using errcode='42501';end if;return(select coalesce(jsonb_agg(x),'[]') from(select day,kind,hits from private.brochure_metrics where brochure_id=p_brochure_id and day>=current_date-30 order by day desc,kind)x);end$$;
revoke all on function private.brochure_resolve(text,text),public.brochure_public(text,text,text,uuid),public.brochure_sitemap(text),public.brochure_submit_lead(text,text,text,jsonb,text),public.brochure_metrics_read(uuid,uuid) from public,anon,authenticated;
grant execute on function public.brochure_public(text,text,text,uuid),public.brochure_sitemap(text),public.brochure_submit_lead(text,text,text,jsonb,text) to anon,authenticated;
grant execute on function public.brochure_metrics_read(uuid,uuid) to authenticated;
commit;
